INSERT INTO news (date, lang, title, text) VALUES
 ('2026-11-14', 'es', 'Ajustes en Jugar en línea', 'El candado de las salas con contraseña ahora está junto al nombre. Los jugadores con una versión antigua de LAIKA se marcan como "Antigua". Los avisos dentro del juego duran lo suficiente para leerlos.'),
 ('2026-11-14', 'en', 'Play online touches', 'The padlock of rooms with a password now sits beside the name. Players on an older LAIKA are marked "Old". Notices in the game last long enough to read them.'),
 ('2026-11-14', 'pt', 'Ajustes no Jogar online', 'O cadeado das salas com senha agora fica ao lado do nome. Quem usa uma versão antiga do LAIKA aparece como "Antiga". Os avisos dentro do jogo duram o bastante para serem lidos.'),
 ('2026-11-14', 'fr', 'Retouches de Jouer en ligne', 'Le cadenas des salons avec mot de passe est maintenant à côté du nom. Les joueurs sur un ancien LAIKA sont marqués « Ancienne ». Les avis en jeu restent assez longtemps pour être lus.'),
 ('2026-11-14', 'it', 'Ritocchi a Gioca online', 'Il lucchetto delle stanze con password ora è accanto al nome. Chi usa una versione vecchia di LAIKA è segnato "Vecchia". Gli avvisi durante il gioco durano abbastanza da poterli leggere.'),
 ('2026-11-14', 'de', 'Feinschliff für Online spielen', 'Das Schloss von Räumen mit Passwort steht jetzt neben dem Namen. Spieler mit einer alten LAIKA-Version sind als "Alt" markiert. Hinweise im Spiel bleiben lange genug zum Lesen.'),
 ('2026-11-14', 'ru', 'Улучшения игры по сети', 'Замок у комнат с паролем теперь рядом с названием. Игроки со старой версией LAIKA отмечены как «Старая». Уведомления в игре держатся достаточно долго, чтобы их прочитать.'),
 ('2026-11-14', 'es', 'Invitaciones para jugar', 'En la sala pulsa RS para invitar a tus amigos o a los jugadores conectados hace poco. Les llega al instante "Erick quiere jugar Smash Bros contigo. Ve al lobby", en el menú o dentro del juego, y Jugar en línea les marca tu sala.'),
 ('2026-11-14', 'en', 'Invitations to play', 'In a room press RS to invite your friends or players online lately. They get "Erick wants to play Smash Bros with you. Go to the lobby" at once, in the menu or over their game, and Play online selects your room for them.'),
 ('2026-11-14', 'pt', 'Convites para jogar', 'Na sala aperte RS para convidar seus amigos ou os jogadores conectados há pouco. Chega na hora "Erick quer jogar Smash Bros com você. Vá ao lobby", no menu ou dentro do jogo, e Jogar online marca a sua sala.'),
 ('2026-11-14', 'fr', 'Invitations à jouer', 'Dans un salon, appuie sur RS pour inviter tes amis ou les joueurs connectés récemment. Ils reçoivent aussitôt « Erick veut jouer à Smash Bros avec toi. Va au salon », dans le menu ou en jeu, et Jouer en ligne sélectionne ton salon.'),
 ('2026-11-14', 'it', 'Inviti a giocare', 'Nella stanza premi RS per invitare i tuoi amici o i giocatori connessi di recente. Ricevono subito "Erick vuole giocare a Smash Bros con te. Vai alla lobby", nel menu o durante il gioco, e Gioca online seleziona la tua stanza.'),
 ('2026-11-14', 'de', 'Einladungen zum Spielen', 'Drücke im Raum RS, um Freunde oder kürzlich verbundene Spieler einzuladen. Sie erhalten sofort "Erick will Smash Bros mit dir spielen. Geh in die Lobby", im Menü oder im Spiel, und Online spielen wählt deinen Raum aus.'),
 ('2026-11-14', 'ru', 'Приглашения в игру', 'В комнате нажми RS, чтобы пригласить друзей или недавно подключившихся игроков. Им сразу приходит «Erick хочет сыграть с тобой в Smash Bros. Зайди в лобби» в меню или во время игры, а Игра по сети выделяет твою комнату.');
